"""Enable only the exact executed replacement cycle; old admission remains byte-identical."""
import pathlib,json,subprocess,datetime
p=pathlib.Path('/private/tmp/financial-retry-192');proof=json.loads((p/'recovery-proof.json').read_text());receipt=json.loads((p/'decision-executed.json').read_text());assert receipt['executed'] and receipt['cycleId']==proof['cycleId'] and receipt['originalPricePreserved'] and receipt['originalFundingHoldPreserved'];assert datetime.datetime.now(datetime.timezone.utc)<datetime.datetime.fromisoformat(proof['expiresAt'].replace('Z','+00:00'));done=[]
def aws(*args):return json.loads(subprocess.check_output(['aws',*args,'--profile','Wizz_stg_UserApp','--region','us-east-1','--output','json']))
for item in json.loads((p/'code-published.json').read_text()):
 name=item['name'];cfg=aws('lambda','get-function-configuration','--function-name',name);original=json.loads((p/(name+'.private.json')).read_text());before=cfg['Environment']['Variables'];assert cfg['CodeSha256']==item['codeSha256'];assert before==original['Environment']['Variables'];after={**before,'FINANCE_DISPATCH_RECOVERY':json.dumps(proof,separators=(',',':'))};file=p/(name+'.recovery-env.private.json');file.write_text(json.dumps({'Variables':after}));file.chmod(0o600)
 aws('lambda','update-function-configuration','--function-name',name,'--revision-id',cfg['RevisionId'],'--environment','file://'+str(file));subprocess.run(['aws','lambda','wait','function-updated-v2','--function-name',name,'--profile','Wizz_stg_UserApp','--region','us-east-1'],check=True)
 live=aws('lambda','get-function-configuration','--function-name',name);assert live['Environment']['Variables']==after;assert all(live.get(k)==cfg.get(k) for k in ['CodeSha256','Role','Handler','MemorySize','Timeout','Runtime']);assert before['FINANCE_ROLLOUT_CONFIG']==after['FINANCE_ROLLOUT_CONFIG'];done.append({'name':name,'verified':True,'originalCohortConfigUnchanged':True,'expiresAt':proof['expiresAt']});(p/'recovery-activated.json').write_text(json.dumps(done,indent=2)+'\n')
print(json.dumps({'functions':done,'proof':proof,'newOrderAdmissionOpened':False}))
